"""
    Parses a user line
    Returns: tuple of (user_id, gender)
    """
def parse_user(line: Any, sep: Any = ',') -> object {
    fields = line.strip().split(sep);
    user_id = int(fields[0]);
    gender = fields[1];
    return (user_id, gender);
}

"""Converts a string argument to a subclass of basestring.

    This comes from `Tornado`_.

    In python2, byte and unicode strings are mostly interchangeable,
    so functions that deal with a user-supplied argument in combination
    with ascii string constants can use either and should return the type
    the user supplied.  In python3, the two types are not interchangeable,
    so this method is needed to convert byte strings to unicode.
    """
def _to_basestring(value: Any) -> object {
    if isinstance(value, str) {
        return value;
    }
    if not isinstance(value, `bytes) {
        raise TypeError(("Expected bytes, unicode, or None; got %r" % `type(value)));
    }
    return value.decode("utf-8");
}

"""
    Convert a tuple or list containing an rgb value to a tuple containing an rgba value.
    rgb : tuple or list of ints or floats ([r, g, b])
    """
def rgb_to_rgba(rgb: Any) -> object {
    r = rgb[0] / 255;
    g = rgb[1] / 255;
    b = rgb[2] / 255;
    return (r, g, b);
}

